    inv[k] = pw(f[k], MOD - 2);
    for (int i = k; i > 0; i--) inv[i - 1] = inv[i] * i % MOD;
    long long ans = 0;
    for (int i = 0; i <= k; i++) {
        long long term = f[k] * inv[i] % MOD * inv[k - i] % MOD * pw(k - i, n) % MOD;
