    for (int i = 2; i <= N; i++) {                    // linear sieve for Mobius
        if (!comp[i]) { primes.push_back(i); mu[i] = -1; }
        for (int p : primes) {
            if ((long long)i * p > N) break;
            comp[i * p] = 1;
            if (i % p == 0) { mu[i * p] = 0; break; }
            mu[i * p] = -mu[i];
        }
    }
    vector<long long> pre(N + 1, 0);
    for (int i = 1; i <= N; i++) pre[i] = pre[i - 1] + mu[i];
