        cin >> a >> b >> k;
        long long A = a / k, B = b / k, res = 0;
        for (long long d = 1, lim = min(A, B); d <= lim;) {
            long long qa = A / d, qb = B / d;
            long long e = min(A / qa, B / qb);        // both quotients constant on [d, e]
            res += (pre[e] - pre[d - 1]) * qa * qb;
            d = e + 1;
        }
