    while (start < d.size() && d[start] == 0) start++;
    while (start < d.size()) {
        int rem = 0;
        for (size_t i = start; i < d.size(); i++) {    // long division by b in base a
            int cur = rem * a + d[i];
            d[i] = cur / b;
            rem = cur % b;
        }
        out += DIG[rem];
        while (start < d.size() && d[start] == 0) start++;
    }
    if (out.empty()) out = "0";
    reverse(out.begin(), out.end());
    cout << out << '\n';
}

